$path = "C:\Users\TAD\emaar-dashboard\src\tabs\HandoverTab.jsx"
$backup = $path + ".bak-professional-rewrite"
Copy-Item $path $backup -Force

$content = [System.Text.Encoding]::UTF8.GetString([System.IO.File]::ReadAllBytes($path))

# Anchor: the entire current transformer block (L135-L179)
# Start: "    const projectsAsHandovers = (Array.isArray(liveProjects) ? liveProjects : [])"
# End: "      });" (the map's closing on L179)

$oldBlock = '    const projectsAsHandovers = (Array.isArray(liveProjects) ? liveProjects : [])' + "`n" + '      .filter(p => p && (p.handoverDate || p.handoverQuarter || p.expectedHandover || p.handover))' + "`n" + '      .map(p => {' + "`n" + '        const hd = String(p.handoverDate || p.contractedHandover || p.expectedHandover || p.handover || "").trim();' + "`n" + '        let quarter = p.handoverQuarter || "";' + "`n" + '        if (!quarter && hd) {' + "`n" + '          const m = hd.match(/(\d{4})/);' + "`n" + '          const year = m ? m[1] : "";' + "`n" + '          const month = hd.includes("January") || hd.includes("February") || hd.includes("March") ? "Q1"' + "`n" + '            : hd.includes("April") || hd.includes("May") || hd.includes("June") ? "Q2"' + "`n" + '            : hd.includes("July") || hd.includes("August") || hd.includes("September") ? "Q3"' + "`n" + '            : hd.includes("October") || hd.includes("November") || hd.includes("December") ? "Q4"' + "`n" + '            : "";' + "`n" + '          if (month && year) quarter = month + " " + year;' + "`n" + '          else if (year) quarter = year;' + "`n" + '        }' + "`n" + '        return {' + "`n" + '          id: p.id || ("live-" + Math.random().toString(36).slice(2)),' + "`n" + '          project: p.project || p.name || "Unnamed Project",' + "`n" + '          developer: p.developer || p.developerName || "Unknown",' + "`n" + '          community: p.community || p.district || "Dubai",' + "`n" + '          type: p.type || "Apartment",' + "`n" + '          handoverQuarter: quarter || "TBD",' + "`n" + '          handoverDate: hd || "",' + "`n" + '          units: p.totalUnits || p.units || p.unitCount || 0,' + "`n" + '          constructionPct: typeof p.constructionPct === "number" ? p.constructionPct : 0,' + "`n" + '          rerVerified: !!(p.reraNo || p.dldNumber || p.projectNumber),' + "`n" + '          onSchedule: (typeof p.constructionPct === "number" ? p.constructionPct : 0) >= 50,' + "`n" + '          delayRiskScore: p.delayRiskScore || (p.tier === 1 ? 15 : 40),' + "`n" + '          startingPrice: p.priceMin || 0,' + "`n" + '          pricePerSqft: p.ppsf || 0,' + "`n" + '          avgUnitSize: p.avgUnitSize || 0,' + "`n" + '          grossYield: p.grossYield || 0,' + "`n" + '          devOnTimeRate: p.devOnTimeRate || (p.tier === 1 ? 85 : 70),' + "`n" + '          insight: p.overview || p.description || p.insight || "",' + "`n" + '          bedTypes: Array.isArray(p.beds) ? p.beds : Object.keys(p.bedConfig || {}),' + "`n" + '          riskFactors: p.tier === 1 ? ["Tier 1 developer", "DLD verified"] : ["Verify DLD status"],' + "`n" + '          riskLevel: p.tier === 1 ? "low" : "medium",' + "`n" + '          paymentPlan: p.paymentPlan || p.payment || "",' + "`n" + '          appreciationSinceLaunch: p.appreciationSinceLaunch || 0,' + "`n" + '          reraNo: p.reraNo || p.dldNumber || p.projectNumber || "",' + "`n" + '          escrowBank: p.escrowBank || "",' + "`n" + '          isLive: true,  /* flag: DLD-verified live Firestore data */' + "`n" + '        };' + "`n" + '      });'

$c = ([regex]::Matches($content, [regex]::Escape($oldBlock))).Count
Write-Host "Anchor matches: $c"
if ($c -ne 1) {
  Write-Host "Anchor not unique - aborting" -ForegroundColor Red
  exit 1
}

$newBlock = '    // PROFESSIONAL TRANSFORMER - reads real Firestore fields, zero fabricated defaults' + "`n" + '    // Helper: fuzzy developer name lookup (Emaar Properties -> Emaar in DEVELOPER_INDEX)' + "`n" + '    const lookupDevOnTime = (devName) => {' + "`n" + '      if (!devName) return null;' + "`n" + '      const needle = String(devName).toLowerCase().trim();' + "`n" + '      const keys = Object.keys(DEVELOPER_INDEX);' + "`n" + '      for (const k of keys) {' + "`n" + '        const kl = k.toLowerCase();' + "`n" + '        if (kl === needle || needle.includes(kl) || kl.includes(needle)) {' + "`n" + '          return DEVELOPER_INDEX[k].onTime;' + "`n" + '        }' + "`n" + '      }' + "`n" + '      return null; // honest: unknown developer returns null, not a fake default' + "`n" + '    };' + "`n" + '' + "`n" + '    const projectsAsHandovers = (Array.isArray(liveProjects) ? liveProjects : [])' + "`n" + '      .filter(p => p && (p.handover || p.expectedHandover || p.handoverQuarter || p.handoverMonth || p.handoverDate || p.contractedHandover))' + "`n" + '      .map(p => {' + "`n" + '        // FIX 1: Handover quarter - prioritize pre-formatted fields' + "`n" + '        const handoverQuarter = p.handover || p.expectedHandover || p.handoverQuarter || p.handoverMonth || "";' + "`n" + '        const handoverDate = p.handoverDate || p.contractedHandover || p.completionDateDLD || "";' + "`n" + '' + "`n" + '        // FIX 2: Avg unit size - multiple real field names' + "`n" + '        const avgSize = p.unitSizeAvgSqFt || p.avgUnitSize || p.builtUpArea || null;' + "`n" + '        const sizeMin = p.unitSizeMinSqFt || p.sizeMin || null;' + "`n" + '        const sizeMax = p.unitSizeMaxSqFt || p.sizeMax || null;' + "`n" + '' + "`n" + '        // FIX 3: Appreciation - compute from real price history OR return null' + "`n" + '        // Hide for off-plan projects (they dont have meaningful appreciation until handover)' + "`n" + '        let appreciation = null;' + "`n" + '        const isCompleted = p.status === "Ready" || p.status === "Completed" || p.lifecycleStage === "historical" || p.lifecycleStage === "recently-delivered";' + "`n" + '        if (isCompleted && p.priceMinAtLaunch && p.priceMin) {' + "`n" + '          appreciation = Math.round(((p.priceMin - p.priceMinAtLaunch) / p.priceMinAtLaunch) * 100 * 10) / 10;' + "`n" + '        } else if (typeof p.appreciationToHandover === "number") {' + "`n" + '          appreciation = p.appreciationToHandover;' + "`n" + '        } else if (typeof p.appreciationSinceLaunch === "number") {' + "`n" + '          appreciation = p.appreciationSinceLaunch;' + "`n" + '        }' + "`n" + '        // appreciation remains null for off-plan projects - UI will hide the field' + "`n" + '' + "`n" + '        // FIX 4: Dev on-time from DEVELOPER_INDEX (research-backed), not fabricated' + "`n" + '        const devOnTime = lookupDevOnTime(p.developer || p.developerName);' + "`n" + '' + "`n" + '        return {' + "`n" + '          id: p.id || ("live-" + Math.random().toString(36).slice(2)),' + "`n" + '          project: p.project || p.name || "Unnamed Project",' + "`n" + '          developer: p.developer || p.developerName || "Unknown",' + "`n" + '          community: p.community || p.area || "Dubai",' + "`n" + '          type: p.type || p.propertyType || "Apartment",' + "`n" + '          handoverQuarter: handoverQuarter || "TBD",' + "`n" + '          handoverDate: handoverDate,' + "`n" + '          units: p.totalUnits || p.residentialUnits || p.units || null,' + "`n" + '          constructionPct: typeof p.constructionPct === "number" ? p.constructionPct : null,' + "`n" + '          rerVerified: !!(p.reraNo || p.dldProjectNumber || p.projectNumber),' + "`n" + '          onSchedule: typeof p.constructionPct === "number" ? p.constructionPct >= 50 : null,' + "`n" + '          delayRiskScore: null, // Honest - we dont compute this; UI will show risk label only' + "`n" + '          startingPrice: p.priceMin || null,' + "`n" + '          pricePerSqft: p.ppsf || null,' + "`n" + '          avgUnitSize: avgSize,' + "`n" + '          sizeMin: sizeMin,' + "`n" + '          sizeMax: sizeMax,' + "`n" + '          grossYield: typeof p.grossYield === "number" ? p.grossYield : null,' + "`n" + '          grossYieldIsEstimate: !!p.grossYieldIsEstimate,' + "`n" + '          devOnTimeRate: devOnTime, // null if developer not in index - UI should hide or show Industry estimate label' + "`n" + '          insight: p.description || p.overview || p.insight || "",' + "`n" + '          bedTypes: Array.isArray(p.beds) ? p.beds : (p.bedConfig ? Object.keys(p.bedConfig) : []),' + "`n" + '          riskFactors: [' + "`n" + '            p.tier === 1 ? "Tier 1 developer" : null,' + "`n" + '            p.dldRegistered || p.reraRegistered ? "DLD/RERA verified" : null,' + "`n" + '            p.escrowActive ? "Escrow active" : null,' + "`n" + '            typeof p.constructionPct === "number" && p.constructionPct >= 70 ? "Construction advanced" : null,' + "`n" + '          ].filter(Boolean),' + "`n" + '          riskLevel: p.tier === 1 && (p.constructionPct || 0) >= 70 ? "low" : (p.tier === 1 ? "medium-low" : "medium"),' + "`n" + '          paymentPlan: p.paymentPlan || p.payment || "",' + "`n" + '          appreciationSinceLaunch: appreciation, // null for off-plan projects - UI hides the field' + "`n" + '          reraNo: p.reraNo || p.dldProjectNumber || p.projectNumber || "",' + "`n" + '          escrowBank: p.escrowBank || "",' + "`n" + '          tier: p.tier || null,' + "`n" + '          isLive: true,' + "`n" + '          _dataQuality: p.dataQualityScore || null, // for future "verified" badges' + "`n" + '        };' + "`n" + '      });'

$content = $content.Replace($oldBlock, $newBlock)

# Verify
$hasLookup = $content.Contains('lookupDevOnTime')
$hasNewFilter = $content.Contains('p.handover || p.expectedHandover || p.handoverQuarter || p.handoverMonth')
$hasAppreciationNull = $content.Contains('appreciation remains null for off-plan')
$hasOldFakeDefault = $content.Contains('devOnTimeRate: p.devOnTimeRate || (p.tier === 1 ? 85 : 70)')

Write-Host ""
Write-Host "Verification:"
Write-Host "  lookupDevOnTime helper added: $hasLookup"
Write-Host "  New handover filter priority: $hasNewFilter"
Write-Host "  Appreciation null for off-plan: $hasAppreciationNull"
Write-Host "  Old fake default removed: $(-not $hasOldFakeDefault)"

if (-not ($hasLookup -and $hasNewFilter -and $hasAppreciationNull) -or $hasOldFakeDefault) {
  Write-Host "Verification failed - reverting" -ForegroundColor Red
  Copy-Item $backup $path -Force
  exit 1
}

[System.IO.File]::WriteAllBytes($path, [System.Text.Encoding]::UTF8.GetBytes($content))
Write-Host ""
Write-Host "HANDOVER TRANSFORMER PROFESSIONALLY REWRITTEN" -ForegroundColor Green